   function mouseDragged() {
     const x = constrain(mouseX, 0, width);
     const y = constrain(mouseY, 0, height);

     if (cropMode === 'drawing') {
       cropEnd = { x, y };
     } else if (cropMode === 'adjusting' && activeHandle) {
       // Update the appropriate corner/edge based on active handle
       updateCropRectangle(activeHandle, x, y);
     }
   }

   function mouseReleased() {
     if (cropMode === 'drawing') {
       // Transition to adjustment mode
       cropMode = 'adjusting';
     }
     activeHandle = null;
   }

   function keyPressed() {
     if (keyCode === ENTER && cropMode === 'adjusting') {
       commitCrop();
       cropMode = 'idle';
     } else if (keyCode === ESCAPE && cropMode !== 'idle') {
       cancelCrop();
       cropMode = 'idle';
     }
   }
